            "id": track_id,
            "title": track["title"],
            "artist": track["artist"],
            "seconds": track["seconds"],
            "explicit": track["explicit"],
            "clock": clock
        })

    return {
        "ok": True,
        "count": len(result_tracks),
        "total_seconds": total_seconds,
        "total_clock": total_clock,
        "tracks": result_tracks
